/**
 * `no-cycle` does not report inside generated files.
 *
 * It is the second-largest source of findings on the pinned corpus — 1337 —
 * and the triage ledger says what they are: "Correct — real circular imports,
 * concentrated in generated SDK class hierarchies." Correct, and unactionable:
 * you do not refactor a file your codegen rewrites, and this rule's own remedy
 * (split the module) is not available to the consumer.
 *
 * Both directions are locked here. The generated case is the change; the plain
 * case is the control that proves the fixture produces a cycle at all, without
 * which "no findings" would mean nothing.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { Linter } from 'eslint';
import tsParser from '@typescript-eslint/parser';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { noCycle } from '../rules/no-cycle';

let dir: string;

const CYCLE_A = "import { b } from './b';\nexport const a = () => b();\n";
const CYCLE_B = "import { a } from './a';\nexport const b = () => a();\n";
/**
 * NOTE the absence of `/* eslint-disable *\/`. The first version of this
 * fixture opened with one, as real generated files often do — and that
 * silences every rule, so the test passed with `skipGeneratedFiles` removed.
 * The banner must be the ONLY thing suppressing the report.
 */
const GENERATED_BANNER = '// Code generated by openapi-generator. DO NOT EDIT.\n';

beforeAll(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'no-cycle-gen-'));
  fs.writeFileSync(path.join(dir, 'b.ts'), CYCLE_B);
});

afterAll(() => {
  if (dir) fs.rmSync(dir, { recursive: true, force: true });
});

const lint = (source: string): Linter.LintMessage[] => {
  const file = path.join(dir, 'a.ts');
  fs.writeFileSync(file, source);
  // cwd matters: the rule takes its workspace root from context.cwd, and a
  // fixture in /tmp against the repo's cwd never resolves.
  const linter = new Linter({ configType: 'flat', cwd: dir });
  return linter.verify(
    source,
    [
      {
        files: ['**/*.ts'],
        languageOptions: {
          parser: tsParser as never,
          ecmaVersion: 2022,
          sourceType: 'module',
        },
        plugins: { 'import-next': { rules: { 'no-cycle': noCycle as never } } },
        rules: { 'import-next/no-cycle': 'error' },
      },
    ],
    file,
  );
};

describe('no-cycle and generated files', () => {
  it('reports a cycle in ordinary source — the control', () => {
    // Without this, the generated assertion below proves nothing: a fixture
    // that produces no cycle at all is silent for the wrong reason.
    const found = lint(CYCLE_A).filter((m) => m.ruleId === 'import-next/no-cycle');
    expect(found.length).toBeGreaterThan(0);
  });

  it('stays silent on the same cycle in a generated file', () => {
    const found = lint(GENERATED_BANNER + CYCLE_A).filter(
      (m) => m.ruleId === 'import-next/no-cycle',
    );
    expect(found).toEqual([]);
  });
});
